import{_ as a,o as l,c as t,a4 as r}from"./chunks/framework.DzJZdBQK.js";const i="/assets/annotation.BitGSK4C.mp4",o="/assets/createproject.yqxf13aB.png",n="/assets/importdataset.B0i1yxcW.png",s="/assets/newlable.Dq6kBueZ.png",h="/assets/adduser.B8zdXUWw.png",g=JSON.parse('{"title":"如何使用写作练习词性标注工具","description":"","frontmatter":{"date":"2020-08-10T23:55:34","title":"如何使用写作练习词性标注工具","categories":["教程100","写作"],"tags":["教程100","写作"]},"headers":[{"level":2,"title":"说明","slug":"说明","link":"#说明","children":[]},{"level":2,"title":"注册与登录","slug":"注册与登录","link":"#注册与登录","children":[]},{"level":2,"title":"标注《七年就是一辈子》","slug":"标注《七年就是一辈子》","link":"#标注《七年就是一辈子》","children":[]},{"level":2,"title":"标注","slug":"标注","link":"#标注","children":[{"level":3,"title":"标注方法","slug":"标注方法","link":"#标注方法","children":[]},{"level":3,"title":"学习","slug":"学习","link":"#学习","children":[]}]},{"level":2,"title":"创建项目","slug":"创建项目","link":"#创建项目","children":[{"level":3,"title":"创建项目","slug":"创建项目-1","link":"#创建项目-1","children":[]},{"level":3,"title":"导入文章（数据集）","slug":"导入文章-数据集","link":"#导入文章-数据集","children":[]},{"level":3,"title":"创建标签","slug":"创建标签","link":"#创建标签","children":[]},{"level":3,"title":"邀请小伙伴","slug":"邀请小伙伴","link":"#邀请小伙伴","children":[]}]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[{"level":3,"title":"注册提示用户名或者昵称被占用","slug":"注册提示用户名或者昵称被占用","link":"#注册提示用户名或者昵称被占用","children":[]},{"level":3,"title":"忘记密码问题","slug":"忘记密码问题","link":"#忘记密码问题","children":[]},{"level":3,"title":"为什么我看不到“七年就是一辈子”项目","slug":"为什么我看不到-七年就是一辈子-项目","link":"#为什么我看不到-七年就是一辈子-项目","children":[]},{"level":3,"title":"导入数据集出现乱码","slug":"导入数据集出现乱码","link":"#导入数据集出现乱码","children":[]},{"level":3,"title":"BUG反馈","slug":"bug反馈","link":"#bug反馈","children":[]},{"level":3,"title":"其他问题","slug":"其他问题","link":"#其他问题","children":[]}]},{"level":2,"title":"感谢","slug":"感谢","link":"#感谢","children":[]}],"relativePath":"posts/course100/001.md","filePath":"posts/course100/001.md"}'),c={name:"posts/course100/001.md"};function d(p,e,u,b,q,k){return l(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><p>由小熊老师组织的笑来写作课作业群“且慢且慢且慢”，在晓樱的发动下，开始做《七年就是一辈子》的词性标注。我看到群里传文件比较麻烦，而且标注可能在不同电脑上，不利于标注的整理。而标注的方式和我去年做的一款医学知识标注工具类似，于是改了部分功能，部署起来方便大家标注。</p><p>下面我说说该工具如何使用。</p><p><strong>重要</strong>：本工具主要是在Chrome浏览器中开发测试，请尽可能使用Chrome浏览器。</p><h2 id="注册与登录" tabindex="-1">注册与登录 <a class="header-anchor" href="#注册与登录" aria-label="Permalink to &quot;注册与登录&quot;">​</a></h2><p>用浏览器打开<a href="http://annotation.goldsyear.com/" target="_blank" rel="noreferrer">http://annotation.goldsyear.com/</a>，此时出现登录界面，如果有用户可直接登录。</p><p>无用户时需要先注册，点击“注册”链接。填写用户名，昵称，密码，注意用户名和密码为登录使用，而昵称主要用于区分不同的标注人。</p><h2 id="标注《七年就是一辈子》" tabindex="-1">标注《七年就是一辈子》 <a class="header-anchor" href="#标注《七年就是一辈子》" aria-label="Permalink to &quot;标注《七年就是一辈子》&quot;">​</a></h2><p>标注的项目采用邀请制，项目创建者和已被邀请的小伙伴可以添加其他小伙伴共同标注项目。如果需要标注其他项目，可以参看“创建项目”小节。</p><p>“七年就是一辈子”项目由admin@box.com用户创建，密码已公布在群里，请翻看聊天记录。当然，也可联系我（罗发强）或者小熊老师进行用户添加，以后会有更多小伙伴可以添加，这里就不再赘述了。</p><p>有了项目权限后，点击“七年就是一辈子”即可进入标注页面。</p><p><video controls preload="metadata" src="'+i+'"></video></p><h2 id="标注" tabindex="-1">标注 <a class="header-anchor" href="#标注" aria-label="Permalink to &quot;标注&quot;">​</a></h2><h3 id="标注方法" tabindex="-1">标注方法 <a class="header-anchor" href="#标注方法" aria-label="Permalink to &quot;标注方法&quot;">​</a></h3><p>把需要的词划出来（点击鼠标左键并摁住不放，滑动鼠标，松开鼠标左键），之后用鼠标点击对应的词性按钮，一个词就标注出来了。词性按钮后由字母标识，是快捷键，把词划选出来后，也可以在键盘上按下对应键把词性标注出来。</p><h3 id="学习" tabindex="-1">学习 <a class="header-anchor" href="#学习" aria-label="Permalink to &quot;学习&quot;">​</a></h3><p>如果有其他小伙伴已经标注了，在页面上会出现该小伙伴的昵称。点击该小伙伴的昵称，就可以看到他标注的情况，开始学习了。</p><h2 id="创建项目" tabindex="-1">创建项目 <a class="header-anchor" href="#创建项目" aria-label="Permalink to &quot;创建项目&quot;">​</a></h2><p>如果想发起新的标注项目，可以自己创建项目，导入文章，邀请小伙伴一起来标注。</p><p>新创建的项目默认是私有的，也就是只有创建者可见，其他人是看不可见的。这也是为什么很多人注册后项目列表是空的原因。当其他小伙伴被创建者添加到项目后，这个小伙伴就可以标注项目，同时也获得了邀请其他小伙伴的权限。</p><h3 id="创建项目-1" tabindex="-1">创建项目 <a class="header-anchor" href="#创建项目-1" aria-label="Permalink to &quot;创建项目&quot;">​</a></h3><p>进入主页，点击“创建项目”，填写项目名称，点击“确定”，完成项目创建。之后点击项目列表上的“编辑”页面进行后续设置。</p><p><img src="'+o+'" alt=""></p><h3 id="导入文章-数据集" tabindex="-1">导入文章（数据集） <a class="header-anchor" href="#导入文章-数据集" aria-label="Permalink to &quot;导入文章（数据集）&quot;">​</a></h3><p>点击“数据集”，点击“导入数据集”，在弹出的对话框中，选择需要导入的文件，当前支持<code>txt</code>和<code>md</code>格式的文件单独导入。也可以把多个<code>txt</code>文件打包成<code>zip</code>文件导入。</p><p><img src="'+n+'" alt=""></p><h3 id="创建标签" tabindex="-1">创建标签 <a class="header-anchor" href="#创建标签" aria-label="Permalink to &quot;创建标签&quot;">​</a></h3><p>点击“标签”，点击“创建标签”，填写标签名称，快捷键，背景颜色，点击“确定”，完成标签的创建。</p><p><img src="'+s+'" alt=""></p><h3 id="邀请小伙伴" tabindex="-1">邀请小伙伴 <a class="header-anchor" href="#邀请小伙伴" aria-label="Permalink to &quot;邀请小伙伴&quot;">​</a></h3><p>点击“用户”，点击“添加用户”，选择用户，角色，点击“保存”，完成小伙伴的添加。</p><p><img src="'+h+'" alt=""></p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="注册提示用户名或者昵称被占用" tabindex="-1">注册提示用户名或者昵称被占用 <a class="header-anchor" href="#注册提示用户名或者昵称被占用" aria-label="Permalink to &quot;注册提示用户名或者昵称被占用&quot;">​</a></h3><blockquote><p>用户名和昵称系统内是唯一的，请尝试更换用户名和昵称，重新注册。</p></blockquote><h3 id="忘记密码问题" tabindex="-1">忘记密码问题 <a class="header-anchor" href="#忘记密码问题" aria-label="Permalink to &quot;忘记密码问题&quot;">​</a></h3><blockquote><p>该工具原来是一个内部工具，用户管理的功能做的比较简单，用户注册也是临时添加的功能，导致不支持修改密码。当前只能添加我的微信进行密码重置。</p></blockquote><h3 id="为什么我看不到-七年就是一辈子-项目" tabindex="-1">为什么我看不到“七年就是一辈子”项目 <a class="header-anchor" href="#为什么我看不到-七年就是一辈子-项目" aria-label="Permalink to &quot;为什么我看不到“七年就是一辈子”项目&quot;">​</a></h3><blockquote><p>标注的项目采用邀请制，项目创建者和已被邀请的小伙伴可以添加其他小伙伴共同标注项目。可在作业群“且慢且慢且慢”反馈自己的用户名，我看到之后会及时添加用户的。</p></blockquote><h3 id="导入数据集出现乱码" tabindex="-1">导入数据集出现乱码 <a class="header-anchor" href="#导入数据集出现乱码" aria-label="Permalink to &quot;导入数据集出现乱码&quot;">​</a></h3><blockquote><p>导入的数据集只支持UTF-8格式，其他格式如GBK（一般Windows默认创建的文本使用了该编码）会出现乱码。需要注意用“记事本”保存（或另存为）时注意选择编码格式UTF-8。</p></blockquote><h3 id="bug反馈" tabindex="-1">BUG反馈 <a class="header-anchor" href="#bug反馈" aria-label="Permalink to &quot;BUG反馈&quot;">​</a></h3><blockquote><p>可以通过以下几种方式进行BUG反馈：</p><ul><li>通过微信公众号CrazyAirhead的推文<a href="https://mp.weixin.qq.com/s/Qoc3SFdL8z42UcwcWn3R7g" target="_blank" rel="noreferrer">如何使用写作练习词性标注工具</a>进行留言。</li><li>通过我的个人Blog<a href="https://l4qiang.me" target="_blank" rel="noreferrer">CrazyAirhead</a>的博文<a href="https://l4qiang.me/2020/08/10/course100/001/" target="_blank" rel="noreferrer">如何使用写作练习词性标注工具</a>进行留言。</li><li>我也专门开了个Github仓库<a href="https://github.com/crazy-airhead/writing/issues" target="_blank" rel="noreferrer">writing</a>，可以在这里提issues。</li><li>当然你可以添加我的微信，反馈问题。</li></ul></blockquote><h3 id="其他问题" tabindex="-1">其他问题 <a class="header-anchor" href="#其他问题" aria-label="Permalink to &quot;其他问题&quot;">​</a></h3><blockquote><p>扫码添加我的微信&quot;Crazy_Airhead&quot;。 <img src="https://l4qiang.me/images/wechat.png" alt=""></p></blockquote><h2 id="感谢" tabindex="-1">感谢 <a class="header-anchor" href="#感谢" aria-label="Permalink to &quot;感谢&quot;">​</a></h2><p>感谢群友的鼓励和建议，感谢小熊老师，量体才一的测试，感谢果兒的BUG反馈。</p>',47)])])}const f=a(c,[["render",d]]);export{g as __pageData,f as default};
